        public HttpResponseMessage GetParentAccountId(string id, string parentId)
        {
            try
            {
                string token = HttpContext.Current.Request.Headers["Token"];
                AuthenticationToken authToken = AuthenticationTokenRepository.GetSingleTokenFromCache(token);
                SecurityUtility.AuthenticationOnTenant(authToken.Tenant);
                SecurityUtility.CheckContactFeature("GLAccount", "READ", authToken.Tenant);

                IAccountingContext MyContext = AccountingContext.GetContext(authToken.Tenant);
                GLAccountQueryService gLAccountQuery = new GLAccountQueryService(MyContext);
                GLAccountPM gLAccountPM = gLAccountQuery.GetSingle(id, false, false);
                GLAccountUpdateService service = new GLAccountUpdateService(MyContext, new Dictionary<string, IContext>(), authToken.Tenant);
                if (parentId.Contains("null"))
                {
                    string[] s = parentId.Split(',');
                    gLAccountPM.Type = "DISC," + s[1] ;
                    gLAccountPM.ParentAccountId = null;
                    gLAccountPM.ChangeSetOp = ChangeSetOperation.Update;
                }
                else
                {
                    gLAccountPM.ParentAccountId = parentId;
                    gLAccountPM.Type = "CHILD";
                    gLAccountPM.ChangeSetOp = ChangeSetOperation.Update;

                }
                gLAccountPM.ChangeSetOp = Simplog.Server.Infrastructure.ChangeSetOperation.Update;
               
                service.Update(gLAccountPM, true);

                return Request.CreateResponse(HttpStatusCode.OK, gLAccountPM);
            }
            catch (Exception ex)
            {
                return Request.CreateResponse(HttpStatusCode.BadRequest, ApiExceptionBuilder.BuildException(ex));
            }

        }


        [HttpGet]
        public HttpResponseMessage GetGLAccountsAgingReport(
            string agingForDate,
            string numberOfmonthsbackwards,
            string vendorCustomerId,
            string category1Id,
            string category2Id,
            string category3Id,
            string category4Id,
            string category5Id,
            string collectorId,
            string salesmanId,
            bool isCustomer,
            string groupByDate,
            bool forceUseMonthMethod
            )
        {
            try
            {
                string token = HttpContext.Current.Request.Headers["Token"];
                AuthenticationToken authToken = AuthenticationTokenRepository.GetSingleTokenFromCache(token);
                string loggedUserEmail = authToken.Email;
                SecurityUtility.AuthenticationOnTenant(authToken.Tenant);

                var myAgingReportParam = new AgingReportParam()
                {
                    Tenant = authToken.Tenant,

                    AgingForDate = Convert.ToDateTime(agingForDate),
                    NumberOfmonthsbackwards = Convert.ToUInt32(numberOfmonthsbackwards),
                    VendorCustomerId = (vendorCustomerId == "undefined" || vendorCustomerId == null) ? null : vendorCustomerId,
                    Category1Id = (category1Id == "undefined" || category1Id == null) ? null : category1Id,
                    Category2Id = (category2Id == "undefined" || category2Id == null) ? null : category2Id,
                    Category3Id = (category3Id == "undefined" || category3Id == null) ? null : category3Id,
                    Category4Id = (category4Id == "undefined" || category4Id == null) ? null : category4Id,
                    Category5Id = (category5Id == "undefined" || category5Id == null) ? null : category5Id,
                    CollectorId = (collectorId == "undefined" || collectorId == null) ? null : collectorId,
                    SalesmanId = (salesmanId == "undefined" || salesmanId == null) ? null : salesmanId,
                    AggregateByGLAccountCurrencies = false,

                    Aging4AccountTypeCode = isCustomer == true ? AgingReportParam.Aging4AccountTypeCodeEnum.Customer2 : AgingReportParam.Aging4AccountTypeCodeEnum.ControlAccountOnly1,

                    GroupByDate = groupByDate == "AccountingDate" ? AgingReportParam.DateEnum.AccountingDate : AgingReportParam.DateEnum.DueDate,
                    AgingMethod = forceUseMonthMethod ? AgingReportParam.MethodEnum.TotalByMonthMethod.ToString() : AgingReportParam.MethodEnum.ReconcileOpenBalanceMethod.ToString(),

                    AgingMethod_Options = Enum.GetNames(typeof(AgingReportParam.MethodEnum)).ToList().Aggregate((b4, aftr) => string.Concat(b4, ";", aftr)),
                    GroupByDate_Options = Enum.GetNames(typeof(AgingReportParam.DateEnum)).ToList().Aggregate((b4, aftr) => string.Concat(b4, ";", aftr)),
                    Aging4AccountTypeCode_Options = Enum.GetNames(typeof(AgingReportParam.Aging4AccountTypeCodeEnum)).ToList().Aggregate((b4, aftr) => string.Concat(b4, ";", aftr)),
                };
            
                var agingReport = new AgingReportService(myAgingReportParam);
                agingReport.RunReport();
                List<PeriodM> result = agingReport.MyPeriodList;


                // Get Ex. Rates
                GetRates(authToken.Tenant);

                // Get Tenant Currency
                GetTenantCurrency(authToken.Tenant);

                //Calculate Local Amounts
                decimal sumCol = 0;
                foreach (PeriodM item in result)
                {
                    item.Total = CalculateLocalAmount(item.Total, item.CurrencyId);
                    sumCol += item.Total;
                }

                //
                //PeriodM sumPeriod = new PeriodM()
                //{
                //    Total = sumCol,
                //    AccountId = "Total",
                //};

                //result.Add(sumPeriod);

                // Group By PeriodName 
                var groupedResult = (from a in result
                                     group a by new {a.PeriodName} into g
                                     select new MyPeriodM
                                     {
                                         Total = g.Sum(d => d.Total),
                                         PeriodName = g.Key.PeriodName

                                     } into s
                                     select s);

                return Request.CreateResponse(HttpStatusCode.OK, groupedResult);
            }
            catch (Exception ex)
            {
                return Request.CreateResponse(HttpStatusCode.BadRequest, ApiExceptionBuilder.BuildException(ex));
            }
        }


